/**
 * @param {number} n
 * @param {number[][]} edges
 * @return {number}
 */
var countCompleteComponents = function(n, edges) {
    let graph = Array.from({ length: n }, () => []);
    let visited = new Array(n).fill(false);

    for (let [u, v] of edges) {
        graph[u].push(v);
        graph[v].push(u);
    }

    const dfs = (node, components) => {
        visited[node] = true;
        components.push(node);

        for (let neighbor of graph[node]) {
            if (!visited[neighbor]) {
                dfs(neighbor, components);
            }
        }
    };

    let res = 0;

    for (let i = 0; i < n; i++) {
        if (visited[i]) {
            continue;
        }

        let components = [];
        dfs(i, components);

        const isComplete = components.every(node => graph[node].length === components.length - 1);

        if (isComplete) {
            res++;
        }
    }

    return res;
};

